/* ================= АВТО-СПЕЦИФИКАЦИИ ================= */
function autoKpi(code,inf,G){
  var el=code.split('.').slice(0,3).join('.');
  var crit=Array.isArray(inf.does)?inf.does:[];
  if(!crit.length)return null;
  return {t:'critl',ti:'Критерии — наблюдаемые доказательства',
    d:{el:el+' '+((G.CD[el]||{}).name||''),kpi:code,crit:crit},
    cap:'Каждый критерий — наблюдаемое действие, по которому оценивают владение показателем.',
    memo:'Проверяйте себя по списку: что можете показать делом — то и засчитывается.',auth:1};
}
function autoCluster(id,inf,G){
  var side=id.slice(0,2),d=(G.DET[G.comp]||{});
  var n=(side==='kn'?(d.knowledge||[]).length:(d.skills||[]).length);
  return {t:'loc',ti:'Где это внутри элемента',
    d:{el:G.comp+' '+((G.CD[G.comp]||{}).name||''),kn:(d.knowledge||[]).length,sk:(d.skills||[]).length,
       side:side,item:inf.title.length>28?inf.title.slice(0,27)+'…':inf.title,
       c:(G.CD[G.comp]||{}).sphere==='context'?'ctx':(G.CD[G.comp]||{}).sphere==='people'?'ppl':'prc'},
    cap:'Эта позиция — часть перечня «'+(side==='kn'?'Знания':'Умения и навыки')+'» из '+n+' позиций элемента '+G.comp+'.',
    memo:'Перечень показывает охват владения: на экзамене спросят применение, а не список.',auth:1};
}

